// src/utils/attestations.ts
var getAttestation = async (viemClient, uid, addresses) => {
  const easAddress = addresses?.eas ?? contractAddresses[viemClient.chain.name]?.eas;
  if (!easAddress) {
    throw new Error(`No EAS address found for chain ${viemClient.chain.name}`);
  }
  const attestation = await viemClient.readContract({
    address: easAddress,
    abi: abi2.abi,
    functionName: "getAttestation",
    args: [uid],
    authorizationList: void 0
  });
  return attestation;
};
var getAttestedEventFromTxHash = async (client, hash) => {
  const events = await getAttestedEventsFromTxHash(client, hash);
  if (!events[0]) {
    throw new Error(`No Attested event found in transaction ${hash}`);
  }
  return events[0].args;
};
var getAttestedEventsFromTxHash = async (client, hash) => {
  let tx;
  try {
    tx = await client.waitForTransactionReceipt({ hash });
  } catch (error) {
    throw new Error(`Failed to get transaction receipt for ${hash}: ${error}`);
  }
  const events = (0, import_viem.parseEventLogs)({
    abi: abi2.abi,
    eventName: "Attested",
    logs: tx.logs
  });
  return events;
};

// src/utils/contract.ts
var import_viem3 = require("viem");

// src/utils/contractSafety.ts
var import_viem2 = require("viem");
var assertDeployedContract = (address, label = "contract") => {
  if ((0, import_viem2.isAddressEqual)(address, import_viem2.zeroAddress)) {
    throw new Error(`${label} is not deployed for this chain`);
  }
};
var pickPackagedEscrowObligations = (addresses) => [
  addresses.erc20EscrowObligation,
  addresses.erc20UnconditionalEscrowObligation,
  addresses.erc721EscrowObligation,
  addresses.erc721UnconditionalEscrowObligation,
  addresses.erc1155EscrowObligation,
  addresses.erc1155UnconditionalEscrowObligation,
  addresses.nativeTokenEscrowObligation,
  addresses.nativeTokenUnconditionalEscrowObligation,
  addresses.tokenBundleEscrowObligation,
  addresses.tokenBundleUnconditionalEscrowObligation,
  addresses.attestationEscrowObligation,
  addresses.attestationUnconditionalEscrowObligation,
  addresses.attestationReferenceEscrowObligation,
  addresses.attestationReferenceUnconditionalEscrowObligation,
  addresses.hookEscrowObligation,
  addresses.hooksEscrowObligation
];
var getAtomicPaymentEscrowAttestation = async (viemClient, addresses, escrowUid, options) => {
  const escrow = await getAttestation(viemClient, escrowUid, addresses);
  if (options?.allowUntrustedEscrow) return escrow;
  const supportedEscrows = addresses.packagedEscrowObligations.filter(
    (address) => !(0, import_viem2.isAddressEqual)(address, import_viem2.zeroAddress)
  );
  if (!supportedEscrows.some((address) => (0, import_viem2.isAddressEqual)(address, escrow.attester))) {
    throw new Error(
      [
        `Unsupported escrow attester for AtomicPaymentUtils: ${escrow.attester}.`,
        "The SDK only settles configured Alkahest escrow contracts by default.",
        "Pass { allowUntrustedEscrow: true } only after independently validating the escrow contract and attestation."
      ].join(" ")
    );
  }
  return escrow;
};

// src/utils/contract.ts
var writeContract = async (viemClient, params) => {
  assertDeployedContract(params.address, String(params.functionName ?? "contract"));
  return viemClient.writeContract({
    ...params,
    chain: viemClient.chain
  });
};
var readContract = async (viemClient, params) => {
  return viemClient.readContract({
    ...params,
    authorizationList: void 0
  });
};

