// src/clients/arbiters/confirmation/nonexclusiveUnrevocableConfirmationArbiter.ts
var makeNonexclusiveUnrevocableConfirmationArbiterClient = (viemClient, addresses) => {
  const confirmationMadeEvent = (0, import_viem25.parseAbiItem)(
    "event ConfirmationMade(bytes32 indexed fulfillment, bytes32 indexed escrow)"
  );
  const confirmationRequestedEvent = (0, import_viem25.parseAbiItem)(
    "event ConfirmationRequested(bytes32 indexed fulfillment, address indexed confirmer, bytes32 indexed escrow)"
  );
  return {
    /**
     * Get the arbiter address
     */
    address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
    /**
     * Confirm a fulfillment for an escrow
     * Only the escrow recipient can confirm.
     */
    confirm: async (fulfillment, escrow) => {
      return await viemClient.writeContract({
        address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
        abi: abi23.abi,
        functionName: "confirm",
        args: [fulfillment, escrow],
        account: viemClient.account,
        chain: viemClient.chain
      });
    },
    /**
     * Request confirmation for a fulfillment
     * The fulfillment attester or recipient can request confirmation.
     */
    requestConfirmation: async (fulfillment, escrow) => {
      return await viemClient.writeContract({
        address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
        abi: abi23.abi,
        functionName: "requestConfirmation",
        args: [fulfillment, escrow],
        account: viemClient.account,
        chain: viemClient.chain
      });
    },
    /**
     * Check if a fulfillment is confirmed for an escrow
     */
    isConfirmed: async (fulfillment, escrow) => {
      return await viemClient.readContract({
        address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
        abi: abi23.abi,
        functionName: "confirmations",
        args: [fulfillment, escrow]
      });
    },
    /**
     * Wait for a confirmation event
     */
    waitForConfirmation: async (fulfillment, escrow, pollingInterval) => {
      const logs = await viemClient.getLogs({
        address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
        event: confirmationMadeEvent,
        args: { fulfillment, escrow },
        fromBlock: "earliest",
        toBlock: "latest"
      });
      if (logs.length > 0 && logs[0]) {
        return logs[0].args;
      }
      const optimalInterval = getOptimalPollingInterval(viemClient, pollingInterval ?? 1e3);
      return new Promise((resolve) => {
        const unwatch = viemClient.watchEvent({
          address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
          event: confirmationMadeEvent,
          args: { fulfillment, escrow },
          pollingInterval: optimalInterval,
          onLogs: (logs2) => {
            if (logs2[0]) {
              resolve(logs2[0].args);
              unwatch();
            }
          }
        });
      });
    },
    /**
     * Wait for a confirmation request event
     */
    waitForConfirmationRequest: async (fulfillment, confirmer, escrow, pollingInterval) => {
      const logs = await viemClient.getLogs({
        address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
        event: confirmationRequestedEvent,
        args: { fulfillment, confirmer, escrow },
        fromBlock: "earliest",
        toBlock: "latest"
      });
      if (logs.length > 0 && logs[0]) {
        return logs[0].args;
      }
      const optimalInterval = getOptimalPollingInterval(viemClient, pollingInterval ?? 1e3);
      return new Promise((resolve) => {
        const unwatch = viemClient.watchEvent({
          address: addresses.nonexclusiveUnrevocableConfirmationArbiter,
          event: confirmationRequestedEvent,
          args: { fulfillment, confirmer, escrow },
          pollingInterval: optimalInterval,
          onLogs: (logs2) => {
            if (logs2[0]) {
              resolve(logs2[0].args);
              unwatch();
            }
          }
        });
      });
    }
  };
};

// src/clients/arbiters/confirmation/index.ts
var makeConfirmationArbitersClient = (viemClient, addresses) => {
  const exclusiveRevocable = makeExclusiveRevocableConfirmationArbiterClient(viemClient, addresses);
  const exclusiveUnrevocable = makeExclusiveUnrevocableConfirmationArbiterClient(viemClient, addresses);
  const nonexclusiveRevocable = makeNonexclusiveRevocableConfirmationArbiterClient(viemClient, addresses);
  const nonexclusiveUnrevocable = makeNonexclusiveUnrevocableConfirmationArbiterClient(viemClient, addresses);
  const byOptions = ({ exclusive, revocable }) => {
    if (exclusive && revocable) return exclusiveRevocable;
    if (exclusive) return exclusiveUnrevocable;
    if (revocable) return nonexclusiveRevocable;
    return nonexclusiveUnrevocable;
  };
  return {
    exclusiveRevocable,
    exclusiveUnrevocable,
    nonexclusiveRevocable,
    nonexclusiveUnrevocable,
    byOptions
  };
};

// src/clients/arbiters/general/intrinsicsArbiter.ts
var makeIntrinsicsArbiterClient = (viemClient, addresses) => {
  return {
    /**
     * Get the arbiter address
     */
    address: addresses.intrinsicsArbiter
  };
};

// src/clients/arbiters/general/trivialArbiter.ts
var makeTrivialArbiterClient = (_viemClient, addresses) => ({
  address: addresses.trivialArbiter
});

// src/clients/arbiters/general/index.ts
var makeGeneralArbitersClient = (viemClient, addresses) => {
  const trivial = makeTrivialArbiterClient(viemClient, addresses);
  const intrinsics = makeIntrinsicsArbiterClient(viemClient, addresses);
  const referencesEscrow = makeReferencesEscrowArbiterClient(viemClient, addresses);
  const trustedOracle = makeTrustedOracleArbiterClient(viemClient, addresses);
  const commitmentTrustedOracle = makeCommitmentTrustedOracleArbiterClient(viemClient, addresses);
  const erc8004 = makeERC8004ArbiterClient(viemClient, addresses);
  const trustedOracleFor = (target = "fulfillment") => target === "fulfillment" ? trustedOracle : commitmentTrustedOracle;
  return {
    trivial,
    intrinsics,
    referencesEscrow,
    trustedOracle,
    commitmentTrustedOracle,
    trustedOracleFor,
    erc8004
  };
};

// src/clients/arbiters/index.ts
var makeArbitersClient = (viemClient, addresses) => {
  const generalArbiters = makeGeneralArbitersClient(viemClient, addresses);
  const logicalArbiters = makeLogicalArbitersClient(viemClient, addresses);
  const attestationPropertiesArbiters = makeAttestationPropertiesArbitersClient(viemClient, addresses);
  const confirmationArbiters = makeConfirmationArbitersClient(viemClient, addresses);
  return {
    check: checkArbiter.bind(null, viemClient, addresses),
    general: generalArbiters,
    logical: logicalArbiters,
    attestationProperties: attestationPropertiesArbiters,
    confirmation: confirmationArbiters
  };
};

