// src/clients/obligations/attestation/util.ts
var import_viem28 = require("viem");
var makeAttestationUtilClient = (viemClient, addresses) => {
  return {
    address: addresses.atomicUtils,
    attestAndCreateReferenceEscrow: async (request, escrowData, escrowExpirationTime) => {
      assertDeployedContract(addresses.atomicUtils, "AtomicAttestationUtils");
      assertDeployedContract(addresses.attestationReferenceEscrowObligation, "AttestationReferenceEscrowObligation");
      const hash = await viemClient.writeContract({
        address: addresses.atomicUtils,
        abi: abi26.abi,
        functionName: "attestAndCreateReferenceEscrow",
        args: [addresses.attestationReferenceEscrowObligation, request, escrowData, escrowExpirationTime],
        value: request.data.value,
        chain: viemClient.chain
      });
      const events = await getAttestedEventsFromTxHash(viemClient, hash);
      const receipt = await viemClient.waitForTransactionReceipt({ hash });
      const referenceEscrowEvents = (0, import_viem28.parseEventLogs)({
        abi: abi26.abi,
        eventName: "ReferenceEscrowCreated",
        logs: receipt.logs
      }).filter((event) => (0, import_viem28.isAddressEqual)(event.address, addresses.atomicUtils));
      const created = referenceEscrowEvents.at(-1);
      if (!created) {
        throw new Error(`No ReferenceEscrowCreated event found in transaction ${hash}`);
      }
      const attestation = events.find((event) => event.args.uid === created.args.attestationUid)?.args;
      const escrow = events.find((event) => event.args.uid === created.args.escrowUid)?.args;
      return {
        hash,
        attestation: attestation ?? { uid: created.args.attestationUid },
        escrow: escrow ?? { uid: created.args.escrowUid }
      };
    }
  };
};

// src/clients/obligations/attestation/index.ts
var pickAttestationAddresses = (addresses) => ({
  eas: addresses.eas,
  atomicUtils: addresses.atomicAttestationUtils,
  escrowObligation: addresses.attestationEscrowObligation,
  escrowObligationUnconditional: addresses.attestationUnconditionalEscrowObligation,
  attestationReferenceEscrowObligation: addresses.attestationReferenceEscrowObligation,
  attestationReferenceEscrowObligationUnconditional: addresses.attestationReferenceUnconditionalEscrowObligation
});
var makeAttestationClient = (viemClient, addresses) => {
  return {
    util: makeAttestationUtilClient(viemClient, addresses),
    escrow: makeAttestationEscrowClient(viemClient, addresses)
  };
};

