// src/clients/obligations/erc1155/util.ts
var makeErc1155UtilClient = (viemClient, addresses) => {
  return {
    approveAll: async (tokenContract, purpose) => {
      const to = purpose === "escrow" ? addresses.escrowObligation : purpose === "payment" ? addresses.paymentObligation : addresses.atomicPaymentUtils;
      const hash = await writeContract(viemClient, {
        address: tokenContract,
        abi: abi38.abi,
        functionName: "setApprovalForAll",
        args: [to, true]
      });
      return hash;
    },
    revokeAll: async (tokenContract, purpose) => {
      const to = purpose === "escrow" ? addresses.escrowObligation : purpose === "payment" ? addresses.paymentObligation : addresses.atomicPaymentUtils;
      const hash = await writeContract(viemClient, {
        address: tokenContract,
        abi: abi38.abi,
        functionName: "setApprovalForAll",
        args: [to, false]
      });
      return hash;
    }
  };
};

// src/clients/obligations/erc1155/escrow/default.ts
var erc1155EscrowDecodeFunction = (0, import_viem37.getAbiItem)({
  abi: abi37.abi,
  name: "decodeObligationData"
});
var erc1155EscrowObligationDataType = erc1155EscrowDecodeFunction.outputs[0];
var makeErc1155DefaultEscrowClient = (viemClient, addresses) => {
  const util = makeErc1155UtilClient(viemClient, addresses);
  const getSchema = async () => await viemClient.readContract({
    address: addresses.escrowObligation,
    abi: abi37.abi,
    functionName: "ATTESTATION_SCHEMA",
    authorizationList: void 0
  });
  return {
    address: addresses.escrowObligation,
    getSchema,
    encodeObligationRaw: (data) => {
      return (0, import_viem37.encodeAbiParameters)([erc1155EscrowObligationDataType], [data]);
    },
    encodeObligation: (token, demand) => {
      return (0, import_viem37.encodeAbiParameters)(
        [erc1155EscrowObligationDataType],
        [
          {
            arbiter: demand.arbiter,
            demand: demand.demand,
            token: token.address,
            tokenId: token.id,
            amount: token.value
          }
        ]
      );
    },
    decodeObligation: (obligationData) => {
      return (0, import_viem37.decodeAbiParameters)([erc1155EscrowObligationDataType], obligationData)[0];
    },
    getObligation: async (uid) => {
      const [attestation, schema] = await Promise.all([getAttestation(viemClient, uid, addresses), getSchema()]);
      if (attestation.schema !== schema) {
        throw new Error(`Unsupported schema: ${attestation.schema}`);
      }
      const data = (0, import_viem37.decodeAbiParameters)([erc1155EscrowObligationDataType], attestation.data)[0];
      return {
        ...attestation,
        data
      };
    },
    create: async (price, item, expiration) => {
      const hash = await writeContract(viemClient, {
        address: addresses.escrowObligation,
        abi: abi37.abi,
        functionName: "doObligation",
        args: [
          {
            token: price.address,
            tokenId: price.id,
            amount: price.value,
            arbiter: item.arbiter,
            demand: item.demand
          },
          expiration
        ]
      });
      const attested = await getAttestedEventFromTxHash(viemClient, hash);
      return { hash, attested };
    },
    approveAndCreate: async (price, item, expiration) => {
      await util.approveAll(price.address, "escrow");
      const hash = await writeContract(viemClient, {
        address: addresses.escrowObligation,
        abi: abi37.abi,
        functionName: "doObligation",
        args: [
          {
            token: price.address,
            tokenId: price.id,
            amount: price.value,
            arbiter: item.arbiter,
            demand: item.demand
          },
          expiration
        ]
      });
      const attested = await getAttestedEventFromTxHash(viemClient, hash);
      return { hash, attested };
    },
    collect: async (buyAttestation, fulfillment) => {
      const hash = await writeContract(viemClient, {
        address: addresses.escrowObligation,
        abi: abi37.abi,
        functionName: "collect",
        args: [buyAttestation, fulfillment]
      });
      return hash;
    },
    reclaim: async (buyAttestation) => {
      const hash = await writeContract(viemClient, {
        address: addresses.escrowObligation,
        abi: abi37.abi,
        functionName: "reclaim",
        args: [buyAttestation]
      });
      return hash;
    }
  };
};

// src/clients/obligations/erc1155/escrow/unconditional.ts
