// src/clients/obligations/tokenBundle/util.ts
var makeTokenBundleUtilClient = (viemClient, addresses) => {
  return {
    approve: async (bundle, purpose) => {
      const target = purpose === "escrow" ? addresses.escrowObligation : purpose === "payment" ? addresses.paymentObligation : addresses.atomicPaymentUtils;
      const results = [];
      for (const token of bundle.erc20s) {
        const hash = await writeContract(viemClient, {
          address: token.address,
          abi: abi29.abi,
          functionName: "approve",
          args: [target, token.value]
        });
        results.push(hash);
      }
      const erc721AddressesSet = new Set(bundle.erc721s.map((token) => token.address));
      for (const address of erc721AddressesSet) {
        const hash = await writeContract(viemClient, {
          address,
          abi: abi34.abi,
          functionName: "setApprovalForAll",
          args: [target, true]
        });
        results.push(hash);
      }
      const erc1155AddressesSet = new Set(bundle.erc1155s.map((token) => token.address));
      for (const address of erc1155AddressesSet) {
        const hash = await writeContract(viemClient, {
          address,
          abi: abi38.abi,
          functionName: "setApprovalForAll",
          args: [target, true]
        });
        results.push(hash);
      }
      return results;
    }
  };
};

