// src/deploy.ts
function bytecodeOf(artifact) {
  return artifact.bytecode.object;
}
async function deploy(fn, artifact, args = []) {
  return fn(artifact.abi, bytecodeOf(artifact), args);
}
async function deployAlkahest(deployFn, options) {
  const scope = options?.scope ?? "all";
  const result = {};
  let easAddress = options?.easAddress;
  let easSrAddress = options?.easSrAddress;
  if (options?.eas) {
    easSrAddress = await deploy(deployFn, SchemaRegistry_default2);
    easAddress = await deploy(deployFn, EAS_default2, [easSrAddress]);
  }
  if (!easAddress || !easSrAddress) {
    throw new Error(
      "EAS and SchemaRegistry addresses are required. Either use eas: true to deploy, or provide easAddress and easSrAddress."
    );
  }
  result.eas = easAddress;
  result.easSchemaRegistry = easSrAddress;
  if (scope === "all" || scope === "arbiters") {
    result.trivialArbiter = await deploy(deployFn, TrivialArbiter_default);
    result.trustedOracleArbiter = await deploy(deployFn, TrustedOracleArbiter_default, [easAddress]);
    result.commitmentTrustedOracleArbiter = await deploy(deployFn, CommitmentTrustedOracleArbiter_default);
    result.intrinsicsArbiter = await deploy(deployFn, IntrinsicsArbiter_default);
    result.erc8004Arbiter = await deploy(deployFn, ERC8004Arbiter_default);
    result.referencesEscrowArbiter = await deploy(deployFn, ReferencesEscrowArbiter_default);
    result.allArbiter = await deploy(deployFn, AllArbiter_default);
    result.anyArbiter = await deploy(deployFn, AnyArbiter_default);
    result.attesterArbiter = await deploy(deployFn, AttesterArbiter_default);
    result.recipientArbiter = await deploy(deployFn, RecipientArbiter_default);
    result.refUidArbiter = await deploy(deployFn, RefUidArbiter_default);
    result.revocableArbiter = await deploy(deployFn, RevocableArbiter_default);
    result.schemaArbiter = await deploy(deployFn, SchemaArbiter_default);
    result.uidArbiter = await deploy(deployFn, UidArbiter_default);
    result.timeAfterArbiter = await deploy(deployFn, TimeAfterArbiter_default);
    result.timeBeforeArbiter = await deploy(deployFn, TimeBeforeArbiter_default);
    result.timeEqualArbiter = await deploy(deployFn, TimeEqualArbiter_default);
    result.expirationTimeAfterArbiter = await deploy(deployFn, ExpirationTimeAfterArbiter_default);
    result.expirationTimeBeforeArbiter = await deploy(deployFn, ExpirationTimeBeforeArbiter_default);
    result.expirationTimeEqualArbiter = await deploy(deployFn, ExpirationTimeEqualArbiter_default);
    result.exclusiveRevocableConfirmationArbiter = await deploy(
      deployFn,
      ExclusiveRevocableConfirmationArbiter_default,
      [easAddress]
    );
    result.exclusiveUnrevocableConfirmationArbiter = await deploy(
      deployFn,
      ExclusiveUnrevocableConfirmationArbiter_default,
      [easAddress]
    );
    result.nonexclusiveRevocableConfirmationArbiter = await deploy(
      deployFn,
      NonexclusiveRevocableConfirmationArbiter_default,
      [easAddress]
    );
    result.nonexclusiveUnrevocableConfirmationArbiter = await deploy(
      deployFn,
      NonexclusiveUnrevocableConfirmationArbiter_default,
      [easAddress]
    );
  }
  if (scope === "all" || scope === "obligations") {
    const easArgs = [easAddress, easSrAddress];
    result.erc20EscrowObligation = await deploy(deployFn, ERC20EscrowObligation_default, easArgs);
    result.erc20UnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalERC20EscrowObligation_default,
      easArgs
    );
    result.erc20PaymentObligation = await deploy(deployFn, ERC20PaymentObligation_default, easArgs);
    result.erc721EscrowObligation = await deploy(deployFn, ERC721EscrowObligation_default, easArgs);
    result.erc721UnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalERC721EscrowObligation_default,
      easArgs
    );
    result.erc721PaymentObligation = await deploy(deployFn, ERC721PaymentObligation_default, easArgs);
    result.erc1155EscrowObligation = await deploy(deployFn, ERC1155EscrowObligation_default, easArgs);
    result.erc1155UnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalERC1155EscrowObligation_default,
      easArgs
    );
    result.erc1155PaymentObligation = await deploy(deployFn, ERC1155PaymentObligation_default, easArgs);
    result.tokenBundleEscrowObligation = await deploy(deployFn, TokenBundleEscrowObligation_default, easArgs);
    result.tokenBundleUnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalTokenBundleEscrowObligation_default,
      easArgs
    );
    result.tokenBundlePaymentObligation = await deploy(deployFn, TokenBundlePaymentObligation_default, easArgs);
    result.nativeTokenEscrowObligation = await deploy(deployFn, NativeTokenEscrowObligation_default, easArgs);
    result.nativeTokenUnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalNativeTokenEscrowObligation_default,
      easArgs
    );
    result.nativeTokenPaymentObligation = await deploy(deployFn, NativeTokenPaymentObligation_default, easArgs);
    result.attestationEscrowObligation = await deploy(deployFn, AttestationEscrowObligation_default, easArgs);
    result.attestationUnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalAttestationEscrowObligation_default,
      easArgs
    );
    result.attestationReferenceEscrowObligation = await deploy(deployFn, AttestationReferenceEscrowObligation_default, easArgs);
    result.attestationReferenceUnconditionalEscrowObligation = await deploy(
      deployFn,
      UnconditionalAttestationReferenceEscrowObligation_default,
      easArgs
    );
    result.hookEscrowObligation = await deploy(deployFn, HookEscrowObligation_default, easArgs);
    result.hooksEscrowObligation = await deploy(deployFn, HooksEscrowObligation_default, easArgs);
    result.erc20EscrowHook = await deploy(deployFn, ERC20EscrowHook_default);
    result.erc721EscrowHook = await deploy(deployFn, ERC721EscrowHook_default);
    result.erc1155EscrowHook = await deploy(deployFn, ERC1155EscrowHook_default);
    result.nativeTokenEscrowHook = await deploy(deployFn, NativeTokenEscrowHook_default);
    result.attestationEscrowHook = await deploy(deployFn, AttestationEscrowHook_default, [easAddress]);
    result.attestationReferenceEscrowHook = await deploy(deployFn, AttestationReferenceEscrowHook_default, [
      easAddress,
      easSrAddress
    ]);
    result.stringObligation = await deploy(deployFn, StringObligation_default, easArgs);
    result.commitRevealObligation = await deploy(deployFn, CommitRevealObligation_default, [
      easAddress,
      easSrAddress,
      "0x0000000000000000000000000000000000000000"
    ]);
  }
  if (scope === "all" || scope === "utils") {
    const erc20Payment = result.erc20PaymentObligation;
    const erc721Payment = result.erc721PaymentObligation;
    const erc1155Payment = result.erc1155PaymentObligation;
    const bundlePayment = result.tokenBundlePaymentObligation;
    const nativePayment = result.nativeTokenPaymentObligation;
    const erc20Escrow = result.erc20EscrowObligation;
    const erc1155Escrow = result.erc1155EscrowObligation;
    const bundleEscrow = result.tokenBundleEscrowObligation;
    const nativeEscrow = result.nativeTokenEscrowObligation;
    if (!erc20Payment || !erc721Payment || !erc1155Payment || !nativePayment || !bundlePayment) {
      throw new Error(
        "Cannot deploy utils without obligation addresses. Deploy obligations first or use scope 'all'."
      );
    }
    if (!erc20Escrow || !erc1155Escrow || !nativeEscrow || !bundleEscrow) {
      throw new Error(
        "Cannot deploy splitters without escrow obligation addresses. Deploy obligations first or use scope 'all'."
      );
    }
    const atomicPaymentArgs = [
      easAddress,
      erc20Payment,
      erc721Payment,
      erc1155Payment,
      nativePayment,
      bundlePayment
    ];
    const atomicPaymentUtils = await deploy(deployFn, AtomicPaymentUtils_default, atomicPaymentArgs);
    result.erc20AtomicPaymentUtils = atomicPaymentUtils;
    result.erc721AtomicPaymentUtils = atomicPaymentUtils;
    result.erc1155AtomicPaymentUtils = atomicPaymentUtils;
    result.nativeTokenAtomicPaymentUtils = atomicPaymentUtils;
    result.tokenBundleAtomicPaymentUtils = atomicPaymentUtils;
    result.atomicAttestationUtils = await deploy(deployFn, AtomicAttestationUtils_default, [easAddress]);
    result.erc20Splitter = await deploy(deployFn, ERC20Splitter_default, [easAddress, erc20Escrow]);
    result.erc1155Splitter = await deploy(deployFn, ERC1155Splitter_default, [easAddress, erc1155Escrow]);
    result.nativeTokenSplitter = await deploy(deployFn, NativeTokenSplitter_default, [
      easAddress,
      nativeEscrow
    ]);
    result.tokenBundleSplitter = await deploy(deployFn, TokenBundleSplitter_default, [easAddress, bundleEscrow]);
    result.tokenBundleSplitterUnvalidated = await deploy(deployFn, TokenBundleSplitterUnvalidated_default, [
      easAddress,
      bundleEscrow
    ]);
    result.commitmentERC20Splitter = await deploy(deployFn, CommitmentERC20Splitter_default, [
      easAddress,
      erc20Escrow
    ]);
    result.commitmentERC1155Splitter = await deploy(deployFn, CommitmentERC1155Splitter_default, [
      easAddress,
      erc1155Escrow
    ]);
    result.commitmentNativeTokenSplitter = await deploy(deployFn, CommitmentNativeTokenSplitter_default, [
      easAddress,
      nativeEscrow
    ]);
    result.commitmentTokenBundleSplitter = await deploy(deployFn, CommitmentTokenBundleSplitter_default, [
      easAddress,
      bundleEscrow
    ]);
    result.commitmentTokenBundleSplitterUnvalidated = await deploy(
      deployFn,
      CommitmentTokenBundleSplitterUnvalidated_default,
      [easAddress, bundleEscrow]
    );
  }
  return result;
}

// tests/utils/tokenTestUtils.ts
function createTokenTestExtension() {
  return (client) => ({
    // Get ERC20 token balance
    async getErc20Balance(token, owner) {
      return client.readContract({
        address: token.address,
        abi: MockERC20Permit_default.abi,
        functionName: "balanceOf",
        args: [owner]
      });
    },
    // Get ERC721 token owner
    async getErc721Owner(token) {
      return client.readContract({
        address: token.address,
        abi: MockERC721_default.abi,
        functionName: "ownerOf",
        args: [token.id]
      });
    },
    // Get ERC1155 token balance
    async getErc1155Balance(token, owner) {
      return client.readContract({
        address: token.address,
        abi: MockERC1155_default.abi,
        functionName: "balanceOf",
        args: [owner, token.id]
      });
    }
  });
}

// tests/utils/setup.ts
var wsErrorSuppressionInstalled = false;
var originalConsoleError;
function installWebSocketErrorSuppression() {
  if (wsErrorSuppressionInstalled) return;
  originalConsoleError = console.error;
  console.error = (...args) => {
    const message = args.join(" ");
    if (message.includes("WebSocket connection to") || message.includes("ErrorEvent") || message.includes("error") && message.includes("ws://localhost")) {
      return;
    }
    originalConsoleError(...args);
  };
  wsErrorSuppressionInstalled = true;
}
async function setupTestEnvironment(options) {
  installWebSocketErrorSuppression();
  const port = Math.floor(Math.random() * 1e4) + 5e4;
  const defaultAnvilConfig = {
    port,
    host: "127.0.0.1",
    chainId: 31337
  };
  const anvilConfig = { ...defaultAnvilConfig, ...options?.anvilOptions };
  const anvil = (0, import_anvil.createAnvil)(anvilConfig);
  await anvil.start();
  const chain = {
    ...import_chains.foundry,
    id: anvilConfig.chainId,
    rpcUrls: {
      default: {
        http: [`http://${anvilConfig.host}:${anvilConfig.port}`],
        webSocket: [`ws://${anvilConfig.host}:${anvilConfig.port}`]
      }
    }
  };
  const transport = (0, import_viem49.http)(`http://${anvil.host}:${anvil.port}`, {
    timeout: 6e4
  });
  const alicePrivateKey = (0, import_accounts.generatePrivateKey)();
  const bobPrivateKey = (0, import_accounts.generatePrivateKey)();
  const charliePrivateKey = (0, import_accounts.generatePrivateKey)();
  const aliceAccount = (0, import_accounts.privateKeyToAccount)(alicePrivateKey, { nonceManager: import_viem49.nonceManager });
  const bobAccount = (0, import_accounts.privateKeyToAccount)(bobPrivateKey, { nonceManager: import_viem49.nonceManager });
  const charlieAccount = (0, import_accounts.privateKeyToAccount)(charliePrivateKey, { nonceManager: import_viem49.nonceManager });
  const aliceAddress = aliceAccount.address;
  const bobAddress = bobAccount.address;
  const charlieAddress = charlieAccount.address;
  const testClient = (0, import_viem49.createTestClient)({
    mode: "anvil",
    account: (0, import_accounts.privateKeyToAccount)((0, import_accounts.generatePrivateKey)(), { nonceManager: import_viem49.nonceManager }),
    chain,
    transport
  }).extend(import_viem49.walletActions).extend(import_viem49.publicActions).extend(createTokenTestExtension());
  await testClient.setBalance({
    address: testClient.account.address,
    value: (0, import_viem49.parseEther)("10")
  });
  await testClient.setBalance({
    address: aliceAddress,
    value: (0, import_viem49.parseEther)("10")
  });
  await testClient.setBalance({
    address: bobAddress,
    value: (0, import_viem49.parseEther)("10")
  });
  await testClient.setBalance({
    address: charlieAddress,
    value: (0, import_viem49.parseEther)("10")
  });
  const aliceWalletClient = (0, import_viem49.createWalletClient)({
    account: aliceAccount,
    chain,
    transport,
    pollingInterval: 1e3
  }).extend(import_viem49.publicActions);
  const bobWalletClient = (0, import_viem49.createWalletClient)({
    account: bobAccount,
    chain,
    transport,
    pollingInterval: 1e3
  }).extend(import_viem49.publicActions);
  const charlieWalletClient = (0, import_viem49.createWalletClient)({
    account: charlieAccount,
    chain,
    transport,
    pollingInterval: 1e3
  }).extend(import_viem49.publicActions);
  const deployContractHelper = async (contract, args = []) => {
    const hash = await testClient.deployContract({
      abi: contract.abi,
      bytecode: contract.bytecode.object,
      args
    });
    const receipt = await testClient.waitForTransactionReceipt({ hash });
    return receipt.contractAddress;
  };
  const deployFn = async (abi81, bytecode, args) => {
    const hash = await testClient.deployContract({ abi: abi81, bytecode, args });
    const receipt = await testClient.waitForTransactionReceipt({ hash });
    return receipt.contractAddress;
  };
  const deployed = await deployAlkahest(deployFn, { eas: true });
  const zeroAddr = "0x0000000000000000000000000000000000000000";
  const addresses = {
    ...deployed,
    // These aren't deployed by deployAlkahest but tests expect them in the type
    erc8004Arbiter: deployed.erc8004Arbiter ?? zeroAddr,
    notArbiter: zeroAddr
  };
  const deployObligation = async (contract) => {
    return deployContractHelper(contract, [addresses.eas, addresses.easSchemaRegistry]);
  };
  const mockAddresses = {
    erc20A: "",
    erc20B: "",
    erc20C: "",
    erc721A: "",
    erc721B: "",
    erc721C: "",
    erc1155A: "",
    erc1155B: "",
    erc1155C: ""
  };
  mockAddresses.erc20A = await deployContractHelper(MockERC20Permit_default, ["Token A", "TKA"]);
  mockAddresses.erc20B = await deployContractHelper(MockERC20Permit_default, ["Token B", "TKB"]);
  mockAddresses.erc20C = await deployContractHelper(MockERC20Permit_default, ["Token C", "TKC"]);
  mockAddresses.erc721A = await deployContractHelper(MockERC721_default);
  mockAddresses.erc721B = await deployContractHelper(MockERC721_default);
  mockAddresses.erc721C = await deployContractHelper(MockERC721_default);
  mockAddresses.erc1155A = await deployContractHelper(MockERC1155_default);
  mockAddresses.erc1155B = await deployContractHelper(MockERC1155_default);
  mockAddresses.erc1155C = await deployContractHelper(MockERC1155_default);
  await testClient.writeContract({
    address: mockAddresses.erc20A,
    abi: MockERC20Permit_default.abi,
    functionName: "transfer",
    args: [aliceAddress, (0, import_viem49.parseEther)("1000")]
  });
  await testClient.writeContract({
    address: mockAddresses.erc20B,
    abi: MockERC20Permit_default.abi,
    functionName: "transfer",
    args: [bobAddress, (0, import_viem49.parseEther)("1000")]
  });
  await testClient.writeContract({
    address: mockAddresses.erc721A,
    abi: MockERC721_default.abi,
    functionName: "mint",
    args: [aliceAddress]
  });
  await testClient.writeContract({
    address: mockAddresses.erc721B,
    abi: MockERC721_default.abi,
    functionName: "mint",
    args: [bobAddress]
  });
  await testClient.writeContract({
    address: mockAddresses.erc1155A,
    abi: MockERC1155_default.abi,
    functionName: "mint",
    args: [aliceAddress, 1n, 100n]
  });
  await testClient.writeContract({
    address: mockAddresses.erc1155B,
    abi: MockERC1155_default.abi,
    functionName: "mint",
    args: [bobAddress, 1n, 100n]
  });
  await testClient.writeContract({
    address: mockAddresses.erc20C,
    abi: MockERC20Permit_default.abi,
    functionName: "transfer",
    args: [charlieAddress, (0, import_viem49.parseEther)("1000")]
  });
  await testClient.writeContract({
    address: mockAddresses.erc721C,
    abi: MockERC721_default.abi,
    functionName: "mint",
    args: [charlieAddress]
  });
  await testClient.writeContract({
    address: mockAddresses.erc1155C,
    abi: MockERC1155_default.abi,
    functionName: "mint",
    args: [charlieAddress, 1n, 100n]
  });
  const aliceClient = makeClient(aliceWalletClient, addresses);
  const bobClient = makeClient(bobWalletClient, addresses);
  const charlieClient = makeClient(charlieWalletClient, addresses);
  const wsTransportAlice = (0, import_viem49.webSocket)(`ws://localhost:${anvil.port}`, {
    retryCount: 0,
    timeout: 1e3
  });
  const wsTransportBob = (0, import_viem49.webSocket)(`ws://localhost:${anvil.port}`, {
    retryCount: 0,
    timeout: 1e3
  });
  const wsTransportCharlie = (0, import_viem49.webSocket)(`ws://localhost:${anvil.port}`, {
    retryCount: 0,
    timeout: 1e3
  });
  const aliceWalletClientWs = (0, import_viem49.createWalletClient)({
    account: aliceAccount,
    chain,
    transport: wsTransportAlice,
    pollingInterval: 1e3
  }).extend(import_viem49.publicActions);
  const bobWalletClientWs = (0, import_viem49.createWalletClient)({
    account: bobAccount,
    chain,
    transport: wsTransportBob,
    pollingInterval: 1e3
  }).extend(import_viem49.publicActions);
  const charlieWalletClientWs = (0, import_viem49.createWalletClient)({
    account: charlieAccount,
    chain,
    transport: wsTransportCharlie,
    pollingInterval: 1e3
  }).extend(import_viem49.publicActions);
  const aliceClientWs = makeClient(aliceWalletClientWs, addresses);
  const bobClientWs = makeClient(bobWalletClientWs, addresses);
  const charlieClientWs = makeClient(charlieWalletClientWs, addresses);
  const anvilInitState = await testClient.dumpState();
  return {
    anvil,
    testClient,
    anvilInitState,
    wsTransports: [wsTransportAlice, wsTransportBob, wsTransportCharlie],
    deployContract: deployContractHelper,
    deployObligation,
    alice: {
      address: aliceAddress,
      privateKey: alicePrivateKey,
      client: aliceClient,
      clientWs: aliceClientWs
    },
    bob: {
      address: bobAddress,
      privateKey: bobPrivateKey,
      client: bobClient,
      clientWs: bobClientWs
    },
    charlie: {
      address: charlieAddress,
      privateKey: charliePrivateKey,
      client: charlieClient,
      clientWs: charlieClientWs
    },
    addresses,
    mockAddresses
  };
}

